mapper.select:
	    SELECT a.* FROM artworks a
    LEFT JOIN categories c ON a.category_id = c.id

        a.is_active = 1

            AND (a.title LIKE CONCAT('%', #{q}, '%')
                OR a.medium LIKE CONCAT('%', #{q}, '%')
                OR a.description LIKE CONCAT('%', #{q}, '%'))


            AND (c.name = #{category} OR c.slug = #{category})


            AND a.medium = #{medium}


            AND a.orientation = #{orientation}


            AND a.dominant_color = #{color}


            AND a.price >= #{priceMin}


            AND a.price <= #{priceMax}



        ORDER BY a.price ASC, a.id ASC
        ORDER BY a.price DESC, a.id ASC
        ORDER BY a.created_at DESC, a.id ASC
        ORDER BY a.sold_count DESC, a.view_count DESC, a.id ASC
        ORDER BY a.id ASC

	    LIMIT #{limit} OFFSET #{offset}
